// Este código se ejecuta en un nodo "Code" de n8n.
// Asume que los datos de entrada (items) provienen del nodo anterior
// y tienen la estructura que proporcionaste.

// --- INICIO DEL CÓDIGO PARA N8N ---

// Accedemos al primer item que llega al nodo.
// n8n pasa los datos como un array de 'items'.
// Asumimos que la entrada es un único item, por lo que usamos items[0].
const item = items[0];

// Extraemos el array 'data' del JSON de ese item.
// Según tu entrada: items[0].json será { "data": [ ... ] }
const inputData = item.json.data;

// Generamos un ID base único para este lote de copias (usando un timestamp)
// Esto reemplaza el "123456789" de tu ejemplo.
const baseId = Date.now();

// Mapeamos el array de entrada al formato de 'copies' deseado.
const copies = inputData.map((dataObject, index) => {
  // dataObject es de la forma: { "AIDA": "texto..." } o { "PAS": "texto..." }

  // Obtenemos la primera (y única) clave, que es el formato (ej: "AIDA")
  const format = Object.keys(dataObject)[0];

  // Obtenemos el valor (el texto) usando esa clave
  const text = dataObject[format];

  // Creamos el ID único para esta copia, usando el índice + 1
  const id = `copy_${baseId}_${index + 1}`;

  // Retornamos el nuevo objeto con la estructura deseada
  return {
    id: id,
    format: format,
    text: text,
    isSelected: false,
    isEditable: true
  };
});

// Construimos el objeto de salida final
const output = {
  success: true,
  copies: copies
};

// n8n espera que retornemos un array de items para el siguiente nodo.
// Retornamos un nuevo item que contiene nuestro JSON transformado.
return [
  {
    json: output
  }
];

// --- FIN DEL CÓDIGO PARA N8N ---

